export function applyWarehouse(dataset){
 const groups=[
  ['inventory',['stock-position','available-stock','stock-movement','identified-handling','receiving','putaway','picking','dispatch','count-reconciliation','inventory-cycle'],[['Manage warehouse inventory',['stock-position','available-stock','count-reconciliation','inventory-cycle']],['control storage and movement of warehouse goods',['stock-movement','putaway','picking','dispatch']],['shipping, receiving and putaway',['receiving','putaway','dispatch','inventory-cycle']]]],
  ['wms',['wms-record','wms-receive','wms-putaway','wms-pick','wms-ship','wms-cycle'],[['Use software in order to store materials within a warehouse',['wms-record','wms-putaway','wms-cycle']],['shipping, receiving and picking',['wms-ship','wms-receive','wms-pick','wms-cycle']]]],
  ['layout',['site-conditions','location-map','layout-variants','wms-setup','opening-balance','layout-implementation','layout-cycle'],[['specific conditions of the leather goods company',['site-conditions','layout-cycle']],['Plan the warehouse layout',['location-map','layout-variants','layout-cycle']],['Implement the warehouse management system',['wms-setup','opening-balance','layout-implementation','layout-cycle']]]],
 ]
 const mappings=groups.map(([key,keys,facets])=>registerServiceGroup(dataset,key,keys,facets,{uuid:skills[key],activityId:id}).mapping)
 for(const spec of specs)authorProfessionActivity(dataset,{...spec,id:id(spec.key)})
 for(const mapping of mappings)for(const to of mapping.activity_ids)if(!dataset.decompositions.some(edge=>edge.type==='decomposes_into'&&edge.from===mapping.skill_id&&edge.to===to))dataset.decompositions.push({from:mapping.skill_id,to,type:'decomposes_into',completion_requirement:'required',validation:'proposed',source:professionSource})
 return mappings
}
